def get_chance(n, x, a):
    total_ways = factorial(n)
    x_ways = factorial(x) * factorial(n - x)
    laxative_ways = factorial(x) * factorial(a) * factorial(n - x - a)
    total_drinks = factorial(a)
    total_drunk = factorial(n) - factorial(a)

    probability = (x_ways / total_ways) * ((total_drunk / total_drinks) ** x) * ((total_drunk / total_drunk) ** (total_drunk - x))
    return round(probability, 2)

