from math import factorial
from functools import lru_cache

# Chinese remainder theorem
def chinese_remainder_theorem(moduli, residues):
    n = len(moduli)
    product = 1
    for m in moduli:
        product *= m
    total = 0
    for i in range(n):
        mi = product // moduli[i]
        total += residues[i] * mul_inv(mi, moduli[i]) * mi
    return total % product

# Extended Euclidean Algorithm
def mul_inv(a, b):
    b0 = b
    x0, x1 = 0, 1
    if b == 1:
        return 1
    while a > 1:
        q = a // b
        a, b = b, a % b
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += b0
    return x1

@lru_cache(maxsize=None)
def catalan(n):
    if n == 0:
        return 1
    return catalan(n-1) * (4*n - 2) // (n + 1)

@lru_cache(maxsize=None)
def bell(n, k):
    if n == 0 or k == 0:
        return 0
    elif k == 1:
        return factorial(n)
    else:
        return sum([bell(n-i, k-1) for i in range(n+1) if i <= min(k, n-i)])

def ways_to_choose_toppings(N, R, M):
    moduli = [gcd(M, i) for i in range(2, N+1)]
    residues = [bell(N, R) % moduli[i] for i in range(len(moduli))]
    return chinese_remainder_theorem(moduli, residues)

