import re

def find_repost_chain(name, reposts):
    visited, chain_length = {}, 0
    for repost in reposts:
        if not visited[repost]:
            chain_length = max(chain_length, 1)
            current_name = name
            while current_name in reposts:
                current_name = reposts[current_name]
                chain_length += 1
            chain_length = max(chain_length, len(repost))
            visited[current_name] = repost
    return chain_length

def solve(n, reposts):
    polycarp = 'polycarp'
    return max(
        find_repost_chain(polycarp, reposts),
        find_repost_chain(n, reposts)
    )

