def is_minimum_people(n, relations):
    # If there are less than 6 people, it's impossible for the statement to hold
    if n < 6:
        return "FAIL"

    # Check if the graph represented by relations is a complete graph (every pair of vertices is connected)
    # If it is, then among any six people there are either three pairwise acquainted or three pairwise unacquainted people
    graph = {i: set() for i in range(n)}
    for a, b in relations:
        graph[a].add(b)
        graph[b].add(a)

    for i in range(n):
        if (i in graph and len(graph[i]) >= 3 and len(graph) - len(graph[i]) >= 3):
            return "WIN"

    return "FAIL"

