def restore_numbers(n, divisors):
    counters = [Counter() for _ in range(n)]
    for divisor in divisors:
        if divisor % 2 == 0:
            counters[divisor // 2].update([divisor])
        else:
            counters[divisor // 2].update([divisor, divisor])
