def minimumGroups(n):
    # Build the graph
    graph = defaultdict(list)
    for i in range(n):
        if i != -1:
            graph[i].append(i+1)
            graph[i+1].append(i)

    # Perform DFS to count the number of connected components
    visited = [False] * n
    def dfs(employee):
        if visited[employee]:
            return 0
        visited[employee] = True
        for neighbor in graph[employee]:
            dfs(neighbor)
        return 1

