def shortest(N, edgeList):
    # Create a graph as an adjacency list
    graph = defaultdict(list)
    for start, end, weight in edgeList:
        graph[start].append((weight, end))

    visited = [False] * N
    visited[0] = True
    shortest_paths = [float('inf')] * N
    shortest_paths[0] = 0

    def bfs(start):
        queue = [(0, start)]
        while queue:
            weight, node = queue.pop(0)
            if visited[node]:
                continue
            visited[node] = True
            for new_weight, new_node in graph[node]:
                if not visited[new_node] and weight + new_weight < shortest_paths[new_node]:
                    shortest_paths[new_node] = weight + new_weight
                    queue.append((weight + new_weight, new_node))

    for node in range(N):
        if not visited[node]:
            bfs(node)

    if shortest_paths[N-1] == float('inf'):
        return -1
    return shortest_paths[N-1]
