def union(n1, n2, parent, rank):
    root1 = find(n1, parent)
    root2 = find(n2, parent)
    if root1 == root2:
        return
    if rank[root1] < rank[root2]:
        parent[root1] = root2
    elif rank[root1] > rank[root2]:
        parent[root2] = root1
    else:
        parent[root2] = root1
        rank[root1] += 1

def minimum_cost_of_sending_message(words, costs, messages):
    group_map = defaultdict(lambda: [])
    for i, word in enumerate(words):
        group_map[word].append((i, costs[i]))

    parent = {i: i for i in range(len(words))}
    rank = {i: 0 for i in range(len(words))}
    for word, indices in group_map.items():
        for index, cost in indices:
            union(index, index + len(words), parent, rank)

    cost_mapping = defaultdict(int)
    for i, cost in enumerate(costs):
        cost_mapping[find(i + len(words), parent)] += cost

    min_cost = float('inf')
    for word in messages:
        cost = cost_mapping[find(word, parent)]
        min_cost = min(min_cost, cost)

    return min_cost

